using System;
using Astrea.RunModifiers;
using LittleLeo;
using LittleLeo.Events;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "LacertianScepterOmenData", menuName = "Data/Battle/Omens System/Omen Data/Hevelius/LacertianScepterOmenData")]
public class LacertianScepterOmenData : EndOfTurnOmenData
{
	[Header("Lacertian Scepter Omen Data")]
	[SerializeField]
	protected CurrentCompanions currentCompanions;

	[SerializeField]
	private IntEvent OnModifyMaxHearts;

	public override void Initialize(OmenInstance omenInstance)
	{
		if (ReferenceSingleton<RunModifiersManager>.Instance.RestlessJourneyRunModifier == null)
		{
			OnModifyMaxHearts.Raise(2);
		}
		base.Initialize(omenInstance);
	}

	public override Action GetOmenAction(OmenInstance omenInstance)
	{
		return delegate
		{
			omenInstance.ActivateOmenFeedback();
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.3f, delegate
			{
				ActivateOmen();
			});
		};
	}

	public override void OmenRemoved()
	{
		base.OmenRemoved();
		if (ReferenceSingleton<RunModifiersManager>.Instance.RestlessJourneyRunModifier == null)
		{
			OnModifyMaxHearts.Raise(3);
		}
	}

	protected override Action GetOmenCheckActivationAction(OmenInstance omenInstance)
	{
		return delegate
		{
			if (currentCompanions.ActiveCompanions.Count != 0)
			{
				ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.EndOfTurnOmenActions.Add(GetOmenAction(omenInstance));
			}
		};
	}

	public override string OmenConvertedDescription()
	{
		string omenRawLocalizedDescription = GetOmenRawLocalizedDescription();
		string text = GetEndOfPlayerTurnLocalizedDescription() + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + GetOmenConvertedDescriptionBattleAction().LowercaseFirst();
		return omenRawLocalizedDescription + "\n" + text;
	}
}
